#include <bits/stdc++.h>
using namespace std;

struct Term { bool literal; long long value; string label; };
map<string, vector<Term>> cells;

static string trim(const string &s) {
    size_t a = s.find_first_not_of(" \t\r\n"), b = s.find_last_not_of(" \t\r\n");
    return a == string::npos ? "" : s.substr(a, b - a + 1);
}

vector<Term> parse(const string &expr) {
    vector<Term> terms;
    size_t start = 0;
    while (true) {
        size_t plus = expr.find('+', start);
        string t = trim(expr.substr(start, plus == string::npos ? string::npos : plus - start));
        bool digits = !t.empty() && all_of(t.begin(), t.end(), ::isdigit);
        terms.push_back(digits ? Term{true, stoll(t), ""} : Term{false, 0, t});
        if (plus == string::npos) break;
        start = plus + 1;
    }
    return terms;
}

// DFS from the label just set: any cycle must pass through it.
bool visit(const string &label, set<string> &active, set<string> &done) {
    if (active.count(label)) return true;
    auto it = cells.find(label);
    if (it == cells.end() || done.count(label)) return false;
    active.insert(label);
    bool found = false;
    for (auto &t : it->second)
        if (!t.literal && visit(t.label, active, done)) { found = true; break; }
    active.erase(label);
    done.insert(label);
    return found;
}

// Sum of a cell; nullopt when it references an unset cell (or a cycle).
optional<long long> evaluate(const string &label, set<string> &active, map<string, long long> &memo) {
    auto it = cells.find(label);
    if (it == cells.end() || active.count(label)) return nullopt;
    auto m = memo.find(label);
    if (m != memo.end()) return m->second;
    active.insert(label);
    long long sum = 0;
    for (auto &t : it->second) {
        if (t.literal) { sum += t.value; continue; }
        auto v = evaluate(t.label, active, memo);
        if (!v) return nullopt;
        sum += *v;
    }
    active.erase(label);
    return memo[label] = sum;
}

int main() {
    string line, out;
    while (getline(cin, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.empty()) continue;
        size_t sp = line.find(' ');
        string op = line.substr(0, sp), rest = line.substr(sp + 1);
        if (op == "GET") {
            set<string> active;
            map<string, long long> memo;
            auto v = evaluate(trim(rest), active, memo);
            out += v ? to_string(*v) : "ERROR";
        } else {
            size_t sp2 = rest.find(' ');
            string label = rest.substr(0, sp2), expr = rest.substr(sp2 + 1);
            auto old = cells.find(label);
            optional<vector<Term>> previous;
            if (old != cells.end()) previous = old->second;
            cells[label] = parse(expr);
            set<string> active, done;
            if (visit(label, active, done)) {
                // reject: restore the previous definition
                if (previous) cells[label] = *previous;
                else cells.erase(label);
                out += "ERROR";
            } else out += "OK";
        }
        out += '\n';
    }
    cout << out;
