import java.io.*;
import java.util.*;

public class Main {
    // a term is either a literal (label == null) or a cell reference
    record Term(long value, String label) {}

    static HashMap<String, List<Term>> cells = new HashMap<>();

    static List<Term> parse(String expr) {
        List<Term> terms = new ArrayList<>();
        for (String raw : expr.split("\\+", -1)) {
            String t = raw.strip();
            boolean digits = !t.isEmpty() && t.chars().allMatch(Character::isDigit);
            terms.add(digits ? new Term(Long.parseLong(t), null) : new Term(0, t));
        }
        return terms;
    }

    // DFS from the label just set: any cycle must pass through it.
    static boolean visit(String label, Set<String> active, Set<String> done) {
        if (active.contains(label)) return true;
        List<Term> terms = cells.get(label);
        if (terms == null || done.contains(label)) return false;
        active.add(label);
        boolean found = false;
        for (Term t : terms)
            if (t.label() != null && visit(t.label(), active, done)) { found = true; break; }
        active.remove(label);
        done.add(label);
        return found;
    }

    // Sum of a cell; null when it references an unset cell (or a cycle).
    static Long evaluate(String label, Set<String> active, Map<String, Long> memo) {
        List<Term> terms = cells.get(label);
        if (terms == null || active.contains(label)) return null;
        if (memo.containsKey(label)) return memo.get(label);
        active.add(label);
        long sum = 0;
        for (Term t : terms) {
            if (t.label() == null) { sum += t.value(); continue; }
            Long v = evaluate(t.label(), active, memo);
            if (v == null) return null;
            sum += v;
        }
        active.remove(label);
        memo.put(label, sum);
        return sum;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            if (line.isEmpty()) continue;
            int sp = line.indexOf(' ');
            String op = line.substring(0, sp), rest = line.substring(sp + 1);
            if (op.equals("GET")) {
                Long v = evaluate(rest.strip(), new HashSet<>(), new HashMap<>());
                out.append(v == null ? "ERROR" : v.toString());
            } else {
                int sp2 = rest.indexOf(' ');
                String label = rest.substring(0, sp2), expr = rest.substring(sp2 + 1);
                List<Term> previous = cells.get(label);
                cells.put(label, parse(expr));
                if (visit(label, new HashSet<>(), new HashSet<>())) {
                    // reject: restore the previous definition
                    if (previous != null) cells.put(label, previous);
                    else cells.remove(label);
                    out.append("ERROR");
                } else out.append("OK");
            }
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
	"strings"
)

// a term is either a literal (isLit) or a cell reference
type term struct {
	isLit bool
	value int64
	label string
}

var cells = map[string][]term{}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parse(expr string) []term {
	var terms []term
	for _, raw := range strings.Split(expr, "+") {
		t := strings.TrimSpace(raw)
		if isDigits(t) {
			v, _ := strconv.ParseInt(t, 10, 64)
			terms = append(terms, term{true, v, ""})
		} else {
			terms = append(terms, term{false, 0, t})
		}
	}
	return terms
}

// visit runs a DFS from the label just set: any cycle must pass through it.
func visit(label string, active, done map[string]bool) bool {
	if active[label] {
		return true
	}
	terms, ok := cells[label]
	if !ok || done[label] {
		return false
	}
	active[label] = true
	found := false
	for _, t := range terms {
		if !t.isLit && visit(t.label, active, done) {
			found = true
			break
		}
	}
	delete(active, label)
	done[label] = true
	return found
}

// evaluate sums a cell; ok is false when it references an unset cell (or a cycle).
func evaluate(label string, active map[string]bool, memo map[string]int64) (int64, bool) {
	terms, ok := cells[label]
	if !ok || active[label] {
		return 0, false
	}
	if v, ok := memo[label]; ok {
		return v, true
	}
	active[label] = true
	var sum int64
	for _, t := range terms {
		if t.isLit {
			sum += t.value
			continue
		}
		v, ok := evaluate(t.label, active, memo)
		if !ok {
			return 0, false
		}
		sum += v
	}
	delete(active, label)
	memo[label] = sum
	return sum, true
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for sc.Scan() {
		line := strings.TrimRight(sc.Text(), "\r")
		if line == "" {
			continue
		}
		op, rest, _ := strings.Cut(line, " ")
		if op == "GET" {
			if v, ok := evaluate(strings.TrimSpace(rest), map[string]bool{}, map[string]int64{}); ok {
				w.WriteString(strconv.FormatInt(v, 10))
			} else {
				w.WriteString("ERROR")
			}
		} else {
			label, expr, _ := strings.Cut(rest, " ")
			previous, had := cells[label]
			cells[label] = parse(expr)
			if visit(label, map[string]bool{}, map[string]bool{}) {
				// reject: restore the previous definition
				if had {
					cells[label] = previous
				} else {
					delete(cells, label)
				}
				w.WriteString("ERROR")
			} else {
				w.WriteString("OK")
			}
		}
		w.WriteByte('\n')
	}
}
